use std::fs::{self, File, OpenOptions};
use std::io::{self, Write};
use std::path::Path;
use std::sync::atomic::{AtomicU64, Ordering};

static SERIAL: AtomicU64 = AtomicU64::new(0);

pub fn write_whole(dest: &str, bytes: &[u8]) -> io::Result<()> {
    if !crate::open::under_root(dest) {
        return Err(io::Error::new(io::ErrorKind::PermissionDenied, "destination outside bloturn"));
    }
    let path = Path::new(dest);
    let parent = path.parent().ok_or_else(|| io::Error::new(io::ErrorKind::InvalidInput, "no parent"))?;
    let stem = path.file_name().and_then(|v| v.to_str()).unwrap_or("card");

    for _ in 0..100 {
        let serial = SERIAL.fetch_add(1, Ordering::Relaxed);
        let tmp = parent.join(format!(".{}.{}.{}.tmp", stem, std::process::id(), serial));
        let mut file = match OpenOptions::new().write(true).create_new(true).open(&tmp) {
            Ok(v) => v,
            Err(e) if e.kind() == io::ErrorKind::AlreadyExists => continue,
            Err(e) => return Err(e),
        };
        let result = (|| {
            file.write_all(bytes)?;
            file.flush()?;
            file.sync_all()?;
            fs::rename(&tmp, path)?;
            File::open(parent)?.sync_all()?;
            Ok(())
        })();
        if result.is_err() {
            let _ = fs::remove_file(&tmp);
        }
        return result;
    }
    Err(io::Error::new(io::ErrorKind::AlreadyExists, "cannot allocate temporary card"))
}
